/**
 * 10–13. Stripe webhook: valid event, invalid signature, duplicate event,
 * cancellation/failure — exercised through the real route handler with
 * signatures generated by the Stripe SDK.
 */
import crypto from "node:crypto";
import { beforeEach, describe, expect, it } from "vitest";
import Stripe from "stripe";
import { POST as webhook } from "@/app/api/stripe/webhook/route";
import { prisma } from "@/lib/server/db";
import { getBalance } from "@/lib/billing/credits";

const stripe = new Stripe("sk_test_unit_dummy");
const SECRET = process.env.STRIPE_WEBHOOK_SECRET!;

let guest: string;
beforeEach(async () => {
  guest = crypto.randomBytes(12).toString("base64url");
  await prisma.guestSession.create({ data: { id: guest } });
});

function checkoutEvent(type: string, overrides: Partial<Stripe.Checkout.Session> = {}, eventId = `evt_${crypto.randomUUID()}`) {
  return {
    id: eventId,
    object: "event",
    type,
    livemode: false,
    created: Math.floor(Date.now() / 1000),
    data: {
      object: {
        id: overrides.id ?? `cs_test_${crypto.randomUUID()}`,
        object: "checkout.session",
        mode: "payment",
        payment_status: "paid",
        status: "complete",
        livemode: false,
        client_reference_id: guest,
        metadata: { guestSessionId: guest, pack: "pack20", credits: "20" },
        ...overrides,
      },
    },
  };
}

function signedRequest(payload: unknown, secret = SECRET) {
  const body = JSON.stringify(payload);
  const sig = stripe.webhooks.generateTestHeaderString({ payload: body, secret });
  return new Request("http://localhost/api/stripe/webhook", { method: "POST", body, headers: { "stripe-signature": sig } });
}

describe("Stripe webhook", () => {
  it("10. valid checkout.session.completed (paid) grants 20 credits", async () => {
    const res = await webhook(signedRequest(checkoutEvent("checkout.session.completed")));
    expect(res.status).toBe(200);
    expect((await res.json()).outcome).toBe("granted");
    expect(await getBalance(guest)).toBe(20);
  });

  it("11. invalid signature is rejected and grants nothing", async () => {
    const bad = await webhook(signedRequest(checkoutEvent("checkout.session.completed"), "whsec_wrong_secret"));
    expect(bad.status).toBe(400);
    const missing = await webhook(
      new Request("http://localhost/api/stripe/webhook", { method: "POST", body: JSON.stringify(checkoutEvent("checkout.session.completed")) }),
    );
    expect(missing.status).toBe(400);
    // Tampered body with a signature for different content
    const original = JSON.stringify(checkoutEvent("checkout.session.completed"));
    const sig = stripe.webhooks.generateTestHeaderString({ payload: original, secret: SECRET });
    const tampered = original.replace('"pack20"', '"pack20" ');
    const t = await webhook(new Request("http://x/api/stripe/webhook", { method: "POST", body: tampered, headers: { "stripe-signature": sig } }));
    expect(t.status).toBe(400);
    expect(await getBalance(guest)).toBe(0);
  });

  it("12. duplicate event replay does not double-grant", async () => {
    const evt = checkoutEvent("checkout.session.completed");
    const r1 = await webhook(signedRequest(evt));
    const r2 = await webhook(signedRequest(evt));
    const r3 = await webhook(signedRequest(evt));
    expect((await r1.json()).outcome).toBe("granted");
    expect((await r2.json()).outcome).toBe("duplicate");
    expect((await r3.json()).outcome).toBe("duplicate");
    expect(await getBalance(guest)).toBe(20);
    expect(await prisma.stripeEvent.count({ where: { id: evt.id } })).toBe(1);
  });

  it("12b. different events for the same Checkout Session grant once", async () => {
    const csId = `cs_test_${crypto.randomUUID()}`;
    await webhook(signedRequest(checkoutEvent("checkout.session.completed", { id: csId })));
    const r = await webhook(signedRequest(checkoutEvent("checkout.session.async_payment_succeeded", { id: csId })));
    expect((await r.json()).outcome).toBe("already_granted");
    expect(await getBalance(guest)).toBe(20);
  });

  it("12c. concurrent replays of the same event grant once", async () => {
    const evt = checkoutEvent("checkout.session.completed");
    await Promise.all(Array.from({ length: 5 }, () => webhook(signedRequest(evt))));
    expect(await getBalance(guest)).toBe(20);
  });

  it("13. cancelled/expired checkout grants nothing", async () => {
    const r = await webhook(signedRequest(checkoutEvent("checkout.session.expired", { payment_status: "unpaid", status: "expired" })));
    expect((await r.json()).outcome).toBe("expired");
    expect(await getBalance(guest)).toBe(0);
  });

  it("13b. async payment: completed(unpaid) waits, failed grants nothing, succeeded grants", async () => {
    const csId = `cs_test_${crypto.randomUUID()}`;
    const r1 = await webhook(signedRequest(checkoutEvent("checkout.session.completed", { id: csId, payment_status: "unpaid" })));
    expect((await r1.json()).outcome).toBe("awaiting_payment");
    expect(await getBalance(guest)).toBe(0);
    const failCs = `cs_test_${crypto.randomUUID()}`;
    const rf = await webhook(signedRequest(checkoutEvent("checkout.session.async_payment_failed", { id: failCs, payment_status: "unpaid" })));
    expect((await rf.json()).outcome).toBe("failed");
    expect(await getBalance(guest)).toBe(0);
    const r2 = await webhook(signedRequest(checkoutEvent("checkout.session.async_payment_succeeded", { id: csId })));
    expect((await r2.json()).outcome).toBe("granted");
    expect(await getBalance(guest)).toBe(20);
  });

  it("rejects events for other products, unknown sessions and live mode", async () => {
    const other = await webhook(signedRequest(checkoutEvent("checkout.session.completed", { metadata: { guestSessionId: guest, pack: "other" } })));
    expect((await other.json()).outcome).toBe("rejected");
    const live = await webhook(signedRequest({ ...checkoutEvent("checkout.session.completed", { livemode: true }) }));
    expect((await live.json()).outcome).toBe("rejected");
    expect(await getBalance(guest)).toBe(0);
  });
});
